window.docContents[30].resolve({"/examples/randint_monte_carlo/proofs/RandintMonteCarloProofs/#mod-doc-examples___randint_monte_carlo___proofs___RandintMonteCarloProofs-1-0":{"contents":"Two ordinary-JAX Monte Carlo examples, proved at estimator boundaries.\nThe uniform/iid laws below are the explicit ideal randint/split specification.\nDeterministic estimator kernels have separate checked Jaxpr certificates.\nNo claim about bitwise PRNG uniformity, seed independence, or floating rounding.","context":"","header":"examples.randint_monte_carlo.proofs.RandintMonteCarloProofs","id":"/examples/randint_monte_carlo/proofs/RandintMonteCarloProofs/#mod-doc-examples___randint_monte_carlo___proofs___RandintMonteCarloProofs-1-0"}});